package com.zipbug.base.licenses

/**
 * Resolves license metadata for apps GENERATED by Zip_Bug (App Creator /
 * AppScaffolder) and builds the per-app license manifest + notices asset
 * that are packaged into every generated project.
 *
 * The known-metadata table below is GENERATED by
 * scripts/generate-licenses.py from the resolved dependency graph
 * (scripts/license-graph.json) and the modules' published POM metadata
 * (scripts/license-pom-metadata.json); verify-project.py fails CI if a
 * bundled license entry is missing here. Any coordinate that is not
 * known is reported as "License review required" — it is never
 * silently relabelled.
 */
object GeneratedLicenseManifest {

    data class KnownLicense(
        val displayName: String,
        val author: String,
        val license: String,
        val licenseUrl: String,
        val category: String
    )

    data class ResolvedDependency(
        val coordinate: String,
        val version: String,
        val known: KnownLicense?
    ) {
        val licenseName: String
            get() = known?.license ?: LicenseEntry.REVIEW_REQUIRED
        val isReviewRequired: Boolean
            get() = known == null
    }

    const val REVIEW_REQUIRED = LicenseEntry.REVIEW_REQUIRED

