    private val COORDINATE =
        Regex("""^([A-Za-z0-9_.\-]+):([A-Za-z0-9_.\-]+):([A-Za-z0-9_.+\-]+)$""")

    /** Resolve full "group:artifact:version" coordinates, de-duplicated. */
    fun resolve(coordinates: List<String>): List<ResolvedDependency> {
        val seen = LinkedHashMap<String, ResolvedDependency>()
        for (raw in coordinates) {
            val m = COORDINATE.matchEntire(raw.trim()) ?: continue
            val ga = "${m.groupValues[1]}:${m.groupValues[2]}"
            if (ga !in seen) {
                seen[ga] = ResolvedDependency(
                    coordinate = ga,
                    version = m.groupValues[3],
                    known = KNOWN[ga]
                )
            }
        }
        return seen.values.toList()
    }

    fun unknownCount(resolved: List<ResolvedDependency>): Int =
        resolved.count { it.isReviewRequired }

    /** license-manifest.json content stored with the generated project. */
    fun buildManifestJson(
        appName: String,
        packageName: String,
        features: List<String>,
        coordinates: List<String>
    ): String {
        val resolved = resolve(coordinates)
        val sb = StringBuilder()
        sb.append("{\n")
        sb.append("  \"appName\": ").append(json(appName)).append(",\n")
        sb.append("  \"packageName\": ").append(json(packageName)).append(",\n")
        sb.append("  \"features\": [")
        sb.append(features.joinToString(", ") { json(it) })
        sb.append("],\n")
        sb.append("  \"libraries\": ").append(resolved.size).append(",\n")
        sb.append("  \"unknown\": ").append(unknownCount(resolved)).append(",\n")
        sb.append("  \"noticesReady\": true,\n")
        sb.append("  \"dependencies\": [\n")
        resolved.forEachIndexed { index, dep ->
            sb.append("    {\n")
            sb.append("      \"name\": ").append(json(dep.coordinate)).append(",\n")
            sb.append("      \"version\": ").append(json(dep.version)).append(",\n")
            sb.append("      \"license\": ").append(json(dep.licenseName)).append("\n")
            sb.append("    }")
            if (index < resolved.size - 1) sb.append(",")
            sb.append("\n")
        }
        sb.append("  ]\n")
        sb.append("}\n")
        return sb.toString()
    }

    /** assets/third_party_notices.txt content for a generated app. */
    fun buildNotices(appName: String, coordinates: List<String>): String {
        val resolved = resolve(coordinates)
        val sb = StringBuilder()
        sb.append("THIRD-PARTY NOTICES — ").append(appName).append("\n\n")
        sb.append("This app was generated with Zip_Bug and includes the ")
        sb.append("open source libraries listed below.\n\n")
        sb.append("Libraries: ").append(resolved.size)
        sb.append("  Unknown: ").append(unknownCount(resolved)).append("\n\n")
        for (dep in resolved) {
            sb.append("=".repeat(72)).append("\n")
            val display = dep.known?.displayName ?: dep.coordinate
            sb.append(display)
            sb.append(" (").append(dep.coordinate).append(":")
            sb.append(dep.version).append(")\n")
            if (dep.known != null) {
                sb.append("Author: ").append(dep.known.author).append("\n")
                sb.append("License: ").append(dep.known.license).append("\n")
                sb.append("License URL: ").append(dep.known.licenseUrl).append("\n")
            } else {
                sb.append("License: ").append(REVIEW_REQUIRED).append("\n")
                sb.append(
                    "The license for this dependency could not be determined " +
                        "automatically. Review it before redistributing this app.\n"
                )
            }
            sb.append("\n")
        }
        return sb.toString()
    }

    private fun json(value: String): String =
        "\"" + value
            .replace("\\", "\\\\")
            .replace("\"", "\\\"")
            .replace("\n", "\\n") + "\""
}
